    raise RuntimeError('The things! They are wrong!')

def testException():
    try:
        raises_exception()
    except Exception:
        print('We caught it!')
    print('The end.')

>>> testException()
We caught it!
The end.
>>>
```

Could you try your program with code  from MPY 1.16, no call to `nlr_call_jump_callbacks(top)`.
```
void nlr_jump(void *val) {
    nlr_buf_t **top_ptr = &MP_STATE_THREAD(nlr_top);
    nlr_buf_t *top = *top_ptr;
    if (top == NULL) {
        nlr_jump_fail(val);
    }
    top->ret_val = val;
    MP_NLR_RESTORE_PYSTACK(top);
    *top_ptr = top->prev;
    longjmp(top->jmpbuf, 1);
}
```
